e" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="type MongoDB\Driver\WriteConcernError" style="color:#EAB766">MongoDB\Driver\WriteConcernError</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php#mongodb-driver-writeresult.props.writeconcernerror">\$<var class="varname">writeConcernError</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766">?</span><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="type MongoDB\Driver\WriteConcern" style="color:#EAB766">MongoDB\Driver\WriteConcern</a></span><span class="type" style="color:#EAB766"></span></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php#mongodb-driver-writeresult.props.writeconcern">\$<var class="varname">writeConcern</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">readonly</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php#mongodb-driver-writeresult.props.errorreplies">\$<var class="varname">errorReplies</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getdeletedcount.php" class="methodname" style="color:#CC7832">getDeletedCount</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getinsertedcount.php" class="methodname" style="color:#CC7832">getInsertedCount</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getmatchedcount.php" class="methodname" style="color:#CC7832">getMatchedCount</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getmodifiedcount.php" class="methodname" style="color:#CC7832">getModifiedCount</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getserver.php" class="methodname" style="color:#CC7832">getServer</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getupsertedcount.php" class="methodname" style="color:#CC7832">getUpsertedCount</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getupsertedids.php" class="methodname" style="color:#CC7832">getUpsertedIds</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getwriteconcernerror.php" class="methodname" style="color:#CC7832">getWriteConcernError</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="type MongoDB\Driver\WriteConcernError" style="color:#EAB766">MongoDB\Driver\WriteConcernError</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.getwriteerrors.php" class="methodname" style="color:#CC7832">getWriteErrors</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-writeresult.isacknowledged.php" class="methodname" style="color:#CC7832">isAcknowledged</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-writeresult.props">   <h2 class="title">属性</h2>   <dl>         <dt id="mongodb-driver-writeresult.props.insertedcount"><var class="varname">insertedCount</var></dt>     <dd>      <span class="simpara">       The number of documents inserted (excluding upserts), or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if       the write concern did not request acknowledgement.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.matchedcount"><var class="varname">matchedCount</var></dt>     <dd>      <span class="simpara">       The number of documents matched by update and replace operations, or       <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the write concern did not request acknowledgement.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.modifiedcount"><var class="varname">modifiedCount</var></dt>     <dd>      <span class="simpara">       The number of documents modified by update and replace operations, or       <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the write concern did not request acknowledgement or if the       server did not report this information.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.deletedcount"><var class="varname">deletedCount</var></dt>     <dd>      <span class="simpara">       The number of documents deleted, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the write concern did       not request acknowledgement.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.upsertedcount"><var class="varname">upsertedCount</var></dt>     <dd>      <span class="simpara">       The number of documents upserted, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if the write concern did       not request acknowledgement.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.server"><var class="varname">server</var></dt>     <dd>      <span class="simpara">       The server that executed the bulk write.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.upsertedids"><var class="varname">upsertedIds</var></dt>     <dd>      <span class="simpara">       An array of <span class="literal">_id</span> values for upserted documents.       Array keys will correspond to the index of the write operation from       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.writeerrors"><var class="varname">writeErrors</var></dt>     <dd>      <span class="simpara">       An array of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeerror.php" class="classname">MongoDB\Driver\WriteError</a></span>s for any       write errors that occurred during execution.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.writeconcernerror"><var class="varname">writeConcernError</var></dt>     <dd>      <span class="simpara">       The <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="classname">MongoDB\Driver\WriteConcernError</a></span> that       occurred, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no write concern error occurred.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.writeconcern"><var class="varname">writeConcern</var></dt>     <dd>      <span class="simpara">       The <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span> used for the       bulk write, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if not available.      </span>     </dd>             <dt id="mongodb-driver-writeresult.props.errorreplies"><var class="varname">errorReplies</var></dt>     <dd>      <span class="simpara">       An array of error reply documents from the server.      </span>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>PECL mongodb 2.3.0</td>       <td>        Added public <span class="modifier">readonly</span> properties.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\WriteResult::getDeletedCount} — Returns the number of documents deleted</li><li>{@link MongoDB\Driver\WriteResult::getInsertedCount} — Returns the number of documents inserted (excluding upserts)</li><li>{@link MongoDB\Driver\WriteResult::getMatchedCount} — Returns the number of documents selected for update</li><li>{@link MongoDB\Driver\WriteResult::getModifiedCount} — Returns the number of existing documents updated</li><li>{@link MongoDB\Driver\WriteResult::getServer} — Returns the server associated with this write result</li><li>{@link MongoDB\Driver\WriteResult::getUpsertedCount} — Returns the number of documents inserted by an upsert</li><li>{@link MongoDB\Driver\WriteResult::getUpsertedIds} — Returns an array of identifiers for upserted documents</li><li>{@link MongoDB\Driver\WriteResult::getWriteConcernError} — Returns any write concern error that occurred</li><li>{@link MongoDB\Driver\WriteResult::getWriteErrors} — Returns any write errors that occurred</li><li>{@link MongoDB\Driver\WriteResult::isAcknowledged} — Returns whether the write was acknowledged</li></ul></div>
 * 
 * The MongoDB\Driver\WriteResult class encapsulates information about an executed MongoDB\Driver\BulkWrite and may be returned by MongoDB\Driver\Manager::executeBulkWrite().
 * @link https://php.net/manual/zh/class.mongodb-driver-writeresult.php
 */
final class WriteResult
{
    /**
     * @since 2.3.0
     */
    public readonly ?int $insertedCount;

    /**
     * @since 2.3.0
     */
    public readonly ?int $matchedCount;

    /**
     * @since 2.3.0
     */
    public readonly ?int $modifiedCount;

    /**
     * @since 2.3.0
     */
    public readonly ?int $deletedCount;

    /**
     * @since 2.3.0
     */
    public readonly ?int $upsertedCount;

    /**
     * @since 2.3.0
     */
    public readonly Server $server;

    /**
     * @since 2.3.0
     */
    public readonly array $upsertedIds;

    /**
     * @since 2.3.0
     */
    public readonly array $writeErrors;

    /**
     * @since 2.3.0
     */
    public readonly ?WriteConcernError $writeConcernError;

    /**
     * @since 2.3.0
     */
    public readonly ?WriteConcern $writeConcern;

    /**
     * @since 2.3.0
     */
    public readonly array $errorReplies;


    final private function __construct() {}


    final public function __wakeup() {}

    /**
 * <div id="mongodb-driver-writeresult.getdeletedcount" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteResult::getDeletedCount</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteResult::getDeletedCount</span> — <span class="dc-title">Returns the number of documents deleted</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeresult.getdeletedcount-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteResult::getDeletedCount</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeresult.getdeletedcount-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeresult.getdeletedcount-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the number of documents deleted.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeresult.getdeletedcount-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-logicexception.php" class="classname">MongoDB\Driver\Exception\LogicException</a></span> if the write was not acknowledged.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-writeresult.getdeletedcount-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">            <tr>        <td>PECL mongodb 2.0.0</td>        <td>         <span class="simpara">          当针对未确认写入调用此方法时，现在会抛出异常，而不是返回 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>。         </span>        </td>       </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeresult.getdeletedcount-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteResult::getDeletedCount()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><s