    /**
 * <div id="mongodb-driver-writeresult.getupsertedids" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteResult::getUpsertedIds</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteResult::getUpsertedIds</span> — <span class="dc-title">Returns an array of identifiers for upserted documents</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeresult.getupsertedids-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteResult::getUpsertedIds</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeresult.getupsertedids-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeresult.getupsertedids-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an array of identifiers (i.e. <span class="literal">"_id"</span> field values)   for upserted documents. The array keys will correspond to the index of the   write operation (from <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>)   responsible for the upsert.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeresult.getupsertedids-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeresult.getupsertedids-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteResult::getUpsertedIds()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'y' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'y' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]], [</span><span style="color: #DD0000">'upsert' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'y' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]], [</span><span style="color: #DD0000">'upsert' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getUpsertedIds</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(2)&nbsp;{<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#4&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"580e62a224f2302f191b880b"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#5&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"580e62a224f2302f191b880c"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeresult.getupsertedids-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\WriteResult::getUpsertedCount()} - Returns the number of documents inserted by an upsert</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\WriteResult::isAcknowledged()} - Returns whether the write was acknowledged</span></li>  </ul> </div></div>
