    /**
 * <div id="mongodb-driver-writeresult.getwriteconcernerror" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteResult::getWriteConcernError</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteResult::getWriteConcernError</span> — <span class="dc-title">Returns any write concern error that occurred</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteResult::getWriteConcernError</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="type MongoDB\Driver\WriteConcernError" style="color:#EAB766">MongoDB\Driver\WriteConcernError</a></span></span></div>  <p class="simpara">  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="classname">MongoDB\Driver\WriteConcernError</a></span> if a write   concern error was encountered during the write operation, and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>   otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteResult::getWriteConcernError()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://rs1.example.com,rs2.example.com/?replicaSet=myReplicaSet"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$writeConcern </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br><br>try {<br>    </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">, [</span><span style="color: #DD0000">'writeConcern' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$writeConcern</span><span style="color: #007700">]);<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception\BulkWriteException \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteResult</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">getWriteConcernError</span><span style="color: #007700">());<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\Driver\WriteConcernError)#6&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;["message"]=&gt;<br>&nbsp;&nbsp;string(33)&nbsp;"waiting&nbsp;for&nbsp;replication&nbsp;timed&nbsp;out"<br>&nbsp;&nbsp;["code"]=&gt;<br>&nbsp;&nbsp;int(64)<br>&nbsp;&nbsp;["info"]=&gt;<br>&nbsp;&nbsp;object(stdClass)#7&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["wtimeout"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeresult.getwriteconcernerror-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/write-concern/" class="link external">»&nbsp;Write Concern reference</a></li>  </ul> </div></div>
