    /**
 * <div id="mongodb-driver-writeresult.getwriteerrors" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\WriteResult::getWriteErrors</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\WriteResult::getWriteErrors</span> — <span class="dc-title">Returns any write errors that occurred</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-writeresult.getwriteerrors-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\WriteResult::getWriteErrors</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-writeresult.getwriteerrors-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-writeresult.getwriteerrors-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an array of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeerror.php" class="classname">MongoDB\Driver\WriteError</a></span> objects   for any write errors encountered during the write operation. The array will   be empty if no write errors occurred.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-writeresult.getwriteerrors-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-writeresult.getwriteerrors-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteResult::getWriteErrors()</strong></span> with a single error</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #FF8000">// By default, bulk write operations are executed serially in order and<br> * execution will stop after the first error.<br> <br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">]);<br><br>try {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\BulkWriteException \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteResult</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">getWriteErrors</span><span style="color: #007700">());<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(MongoDB\Driver\WriteError)#5&nbsp;(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["message"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(81)&nbsp;"E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;collection:&nbsp;db.collection&nbsp;index:&nbsp;_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;2&nbsp;}"<br>&nbsp;&nbsp;&nbsp;&nbsp;["code"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(11000)<br>&nbsp;&nbsp;&nbsp;&nbsp;["index"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;&nbsp;&nbsp;["info"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;NULL<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\WriteResult::getWriteErrors()</strong></span> with multiple errors</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">;<br><br></span><span style="color: #FF8000">// The "ordered" option may be used to allow bulk write operations to continue<br> * executing after the first error is encountered.<br> <br></span><span style="color: #9876AA">\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">([</span><span style="color: #DD0000">'ordered' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">]);<br><br>try {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\BulkWriteException \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteResult</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">getWriteErrors</span><span style="color: #007700">());<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(MongoDB\Driver\WriteError)#5&nbsp;(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["message"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(81)&nbsp;"E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;collection:&nbsp;db.collection&nbsp;index:&nbsp;_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;2&nbsp;}"<br>&nbsp;&nbsp;&nbsp;&nbsp;["code"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(11000)<br>&nbsp;&nbsp;&nbsp;&nbsp;["index"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;&nbsp;&nbsp;["info"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;NULL<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(MongoDB\Driver\WriteError)#6&nbsp;(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["message"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(81)&nbsp;"E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;collection:&nbsp;db.collection&nbsp;index:&nbsp;_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;4&nbsp;}"<br>&nbsp;&nbsp;&nbsp;&nbsp;["code"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(11000)<br>&nbsp;&nbsp;&nbsp;&nbsp;["index"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(5)<br>&nbsp;&nbsp;&nbsp;&nbsp;["info"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;NULL<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-writeresult.getwriteerrors-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeerror.php" class="classname">MongoDB\Driver\WriteError</a></span></li>  </ul> </div></div>
